module.render:
const list = (v) => (Array.isArray(v) ? v : String(v == null ? '' : v).replace(/^\[|\]$/g, '').split(/[,\s]+/)).map((s) => String(s).trim()).filter(Boolean);
const num = (v) => { const n = parseFloat(v); return Number.isFinite(n) ? n : null; };
const prefix = String(args.rows || '').trim().replace(/[^\p{L}\p{N}_.-]/gu, '');
let body = sections.join('\n\n').replace(/\r\n/g, '\n');

// The cell-separating pipes of a table row: not in \( \) / \[ \], a code span, or \|.
const pipesOf = (line) => {
  const out = [];
  let i = 0, math = '', code = 0;
  while (i < line.length) {
    const c = line[i];
    if (code) { if (line.startsWith('`'.repeat(code), i)) { i += code; code = 0; } else i++; continue; }
    if (c === '`') { let n = 0; while (line[i + n] === '`') n++; code = n; i += n; continue; }
    if (c === '\\') {
      const nx = line[i + 1];
      if (!math && (nx === '(' || nx === '[')) { math = nx === '(' ? ')' : ']'; i += 2; continue; }
      if (math && nx === math) { math = ''; i += 2; continue; }
      i += 2; continue;
    }
    if (c === '|' && !math) out.push(i);
    i++;
  }
  return out;
};
// [start, end) of each cell's text in a row.
const cellsOf = (line) => {
  const p = pipesOf(line);
  const lead = /^\s*\|/.test(line);
  const edges = lead ? p : [-1].concat(p);
  const cells = [];
  for (let k = 0; k + 1 < edges.length; k++) cells.push([edges[k] + 1, edges[k + 1]]);
  const tail = line.slice((edges[edges.length - 1] || 0) + 1);
  if (tail.trim()) cells.push([edges[edges.length - 1] + 1, line.length]);
  return cells;
};
const DELIM = /^\s*\|?\s*:?-+:?\s*(\|\s*:?-+:?\s*)*\|?\s*$/;

// Find the tables: a header row, the delimiter row, then the body rows.
const lines = body.split('\n');
const findTables = () => {
  const found = [];
  for (let i = 0; i + 1 < lines.length; i++) {
    if (lines[i].includes('|') && DELIM.test(lines[i + 1])) {
      const t = { head: i, rows: [] };
      let j = i + 2;
      while (j < lines.length && lines[j].trim() && lines[j].includes('|')) { t.rows.push(j); j++; }
      found.push(t);
      i = j - 1;
    }
  }
  return found;
};
// A line right under a table would be read as one more row: end each table with
// a blank line, so a note under it ("単位: 時間") stays a note.
findTables().reverse().forEach((t) => {
  const last = t.rows.length ? t.rows[t.rows.length - 1] : t.head + 1;
  if (last + 1 < lines.length && lines[last + 1].trim()) lines.splice(last + 1, 0, '');
});
body = lines.join('\n');
const tables = findTables();

// Numbers of the cells, for best: a value as written (math, bold, % and signs
// allowed; the first number of a range like 16.7〜18.3).
const numOf = (cell) => {
  const s = cell
    .replace(/\\\(|\\\)|\\\[|\\\]|\$|\*\*|__|`/g, '')
    .replace(/\\(?:text|mathrm|mathbf|textbf|boldsymbol)\{([^}]*)\}/g, '$1')
    .replace(/\\[,;:! ]/g, '').replace(/[{}]/g, '').replace(/−|\\minus/g, '-').replace(/,(?=\d{3})/g, '');
  const m = /[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?/.exec(s);
  return m ? parseFloat(m[0]) : null;
};
const bestRules = [];
list(args.best).forEach((b) => {
  const m = /^(\d+)\s*(?::\s*(max|min))?$/i.exec(b);
  if (m) bestRules.push({ col: Number(m[1]), mode: (m[2] || 'max').toLowerCase() });
});
const bold = [];
tables.forEach((t, ti) => {
  bestRules.forEach((r) => {
    const vals = t.rows.map((li) => { const c = cellsOf(lines[li])[r.col - 1]; return c ? numOf(lines[li].slice(c[0], c[1])) : null; });
    const ok = vals.filter((v) => v !== null);
    if (!ok.length) return;
    const target = r.mode === 'min' ? Math.min(...ok) : Math.max(...ok);
    vals.forEach((v, k) => { if (v === target) bold.push({ table: ti + 1, row: k + 1, col: r.col }); });
  });
});

// Row names: the first cell of each body row becomes \focus{PREFIXn}{…}.
if (prefix) {
  let n = 0;
  tables.forEach((t) => t.rows.forEach((li) => {
    n++;
    const line = lines[li];
    const c = cellsOf(line)[0];
    if (!c) return;
    const raw = line.slice(c[0], c[1]);
    const text = raw.trim();
    const lead = raw.slice(0, raw.length - raw.trimStart().length) || ' ';
    const trail = raw.slice(raw.trimEnd().length) || ' ';
    lines[li] = line.slice(0, c[0]) + lead + '\\focus{' + prefix + n + '}{' + text + '}' + trail + line.slice(c[1]);
  }));
  body = lines.join('\n');
}

// The scoped stylesheet.
let h = 0;
const sig = JSON.stringify([body, args]);
for (let i = 0; i < sig.length; i++) h = (h * 31 + sig.charCodeAt(i)) | 0;
const scope = 'mdp-tbl-' + Math.abs(h).toString(36);
const S = '.mdp-mod-table.' + scope;
const nth = (tableNo) => S + ' table:nth-of-type(' + tableNo + ')';
let css = '';
const size = num(args.size), pad = num(args.pad), padx = num(args.padx);
if (size !== null) css += S + ' th, ' + S + ' td { font-size: ' + size + 'em; }\n';
if (pad !== null) css += S + ' th, ' + S + ' td { padding-top: ' + pad + 'em; padding-bottom: ' + pad + 'em; }\n';
if (padx !== null) css += S + ' th, ' + S + ' td { padding-left: ' + padx + 'em; padding-right: ' + padx + 'em; }\n';
const nw = list(args.nowrap);
if (nw.some((c) => /^all$/i.test(c))) css += S + ' th, ' + S + ' td { white-space: nowrap; }\n';
else nw.map(Number).filter((c) => c > 0).forEach((c) => { css += S + ' th:nth-child(' + c + '), ' + S + ' td:nth-child(' + c + ') { white-space: nowrap; }\n'; });
if (String(args.key) === 'true') css += S + ' td:first-child { font-weight: 700; white-space: nowrap; }\n';
const widths = list(args.widths).map(Number).filter((w) => w > 0);
if (widths.length) {
  css += S + ' table { width: 100%; }\n';
  widths.forEach((w, k) => { css += S + ' th:nth-child(' + (k + 1) + ') { width: ' + w + '%; }\n'; });
}
const width = String(args.width || '').trim().replace(/[;"<>{}]/g, '');
if (width) css += S + ' table { width: ' + width + '; }\n';
bold.forEach((b) => {
  const cell = nth(b.table) + ' tbody tr:nth-child(' + b.row + ') td:nth-child(' + b.col + ')';
  css += cell + ', ' + cell + ' .katex { font-weight: 700; }\n';
});
list(args.hl).map(Number).filter((r) => r > 0).forEach((r) => {
  css += S + ' tbody tr:nth-child(' + r + ') > td { background-color: color-mix(in srgb, var(--accent-color, #3b82f6) 14%, var(--bg-color, #fff)); }\n';
});

return '\n\n' + (css ? '<style>' + css + '</style>\n\n' : '') + '<div class="mdp-mod-table ' + scope + '">\n\n' + body.trim() + '\n\n</div>\n\n';
